%% TRAIN_ANFIS
% Step 5: Train the Adaptive Neuro-Fuzzy Inference System on the dataset
% generated by 04_Ideal_Controller_DataGen/generate_training_data.m.
% This is the core "new thing" of your project -- replacing the
% hand-written 49-rule table with a data-learned rule set.

clear; clc; close all;

%% 1) Load training data
dataPath = fullfile('..', '..', 'Data', 'Training_Datasets', 'anfis_training_data.mat');
load(dataPath, 'trainingData'); % columns: [error, d_error, duty]

% Split into train/validation/test (80/10/10)
N = size(trainingData, 1);
idx = randperm(N);
trainingData = trainingData(idx, :); % shuffle

nTrain = round(0.8 * N);
nVal   = round(0.1 * N);

trainSet = trainingData(1:nTrain, :);
valSet   = trainingData(nTrain+1:nTrain+nVal, :);
testSet  = trainingData(nTrain+nVal+1:end, :);

%% 2) Generate initial FIS structure (grid partition, fuzzy c-means also an option)
genOpt = genfisOptions('GridPartition');
genOpt.NumMembershipFunctions = [5 5];   % 5 MFs per input, start small
genOpt.InputMembershipFunctionType = {'gbellmf','gbellmf'};
initialFis = genfis(trainSet(:, 1:2), trainSet(:, 3), genOpt);

%% 3) Train ANFIS
trainOpt = anfisOptions( ...
    'InitialFis', initialFis, ...
    'EpochNumber', 100, ...
    'ValidationData', valSet, ...
    'DisplayANFISInformation', 1, ...
    'DisplayErrorValues', 1);

[trainedFis, trainError, ~, chkFis, chkError] = anfis(trainSet, trainOpt);

%% 4) Evaluate on held-out test set
predicted = evalfis(trainedFis, testSet(:, 1:2));
testRMSE  = sqrt(mean((predicted - testSet(:, 3)).^2));
fprintf('Test RMSE: %.5f\n', testRMSE);

%% 5) Plot training/validation error convergence (Step 5 deliverable plot)
figure;
plot(trainError, 'LineWidth', 1.5); hold on;
plot(chkError, 'LineWidth', 1.5);
xlabel('Epoch'); ylabel('RMSE');
legend('Training error', 'Validation error');
title('ANFIS Training Convergence');
grid on;

outPlot = fullfile('..', '..', 'Results_Plots', 'Comparison_Tables', 'anfis_training_convergence.png');
saveas(gcf, outPlot);

%% 6) Save trained FIS for deployment
outFis = fullfile(fileparts(mfilename('fullpath')), 'anfis_model.fis');
writeFIS(trainedFis, outFis);
fprintf('Saved trained ANFIS model to: %s\n', outFis);

%% 7) Optional: view rule surface
figure;
gensurf(trainedFis);
title('Learned ANFIS Rule Surface (error, d\_error -> duty)');
